			function fullmessage(msg, type) {
				Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg, 'ODM-Translation', type);
			}

			function error(msg) {
				fullmessage(msg, ERRORMESSAGE);
			}

			function message(msg) {
				fullmessage(msg, PLAINMESSAGE);
			}

			function linemessage() {
				str = ''
				for (i=0;i<arguments.length;i++){
					str = str.concat(arguments[i],'\n')
				}
				message(str)
			}

			// simulates the not existing array.forEach method
			// for each element in arr, calls f(elem,idx)
			function forEach(arr,f){
				for (var idx = 0;idx < arr.length; idx++) { 
					f(arr[idx],idx);
				}
			}

			function getAllMappings(rmodels) {
				g_containerMappings = {}
				g_attrMappings = {}
				if (rmodels == null) return
				for (imod = 0; imod < rmodels.length; imod++) {
					rmod = rmodels[imod]
					modname = rmod.getName()
					tables = rmod.getTableSet()
					modelMap = rmod.getRMExtendedMap().getContainerMappings().toArray();
					if (modelMap != null) {
						for (imgm = 0; imgm < modelMap.length; imgm++) {
							logMap = modelMap[imgm]
							relName = tables.getObjectByID(logMap.getRelID())
							switch (logMap.getLogType()) {
								case ENTITYPE:
									logName = g_entitySet.getObjectByID(logMap.getLogID())
									break
								case RELATYPE:
									logName = g_relationSet.getObjectByID(logMap.getLogID())
									break;
								case INHERITTYPE:
									logName = g_inheritanceSet.getObjectByID(logMap.getLogID())
									break;
								default:
									logName = null
							}

							g_containerMappings[logMap.getID()] = {
								modelName: modname,
								logID: logMap.getLogID(),
								logName: logName,
								logType: logMap.getLogType(),
								relID: logMap.getRelID(),
								tableName: relName,
								relType: logMap.getRelType(),
								srcEntityID: logMap.getRealSourceEntityID(),
								trgEntityID: logMap.getRealTargetEntityID()
							}

							containedMaps = logMap.getContainedMappings()
							for (icm = 0; icm < containedMaps.length; icm++) {
								cm = containedMaps[icm]
								g_attrMappings[cm.getID()] = {
									modelName: modname,
									parentID: logMap.getID(),
									logID: cm.getLogID(),
									logType: cm.getLogType(),
									relID: cm.getRelID(),
									relType: cm.getRelType()
								}
							}
						}
					}
				}
			}

			function trimapo(s) {
				return s.replace(/^"|"$/g, '');
			}

			function curDateStr() {
				var currentdate = new Date();
				return currentdate.getDate() +
					"/" + (currentdate.getMonth() + 1) +
					"/" + currentdate.getFullYear() + "  " +
					currentdate.getHours() + ":" +
					currentdate.getMinutes() + ":" + currentdate.getSeconds();
			}

			function getContainerMaps(tabID) {
				maps = []
				for (key in g_containerMappings) {
					if (tabID == g_containerMappings[key].relID) maps.push(g_containerMappings[key])
				}
				return maps
			}

			function getContainerMap(entiID, tabID) {
				for (key in g_containerMappings) {
					if (tabID == g_containerMappings[key].relID && entiID == g_containerMappings[key].logID) return g_containerMappings[key]
				}
				return null
			}

			function getLogMap(logID, modName) {
				maps = []
				for (key in g_containerMappings) {
					if ((logID == g_containerMappings[key].logID) &&
						(modName == g_containerMappings[key].modelName)) maps.push(g_containerMappings[key])
				}
				return maps
			}

			function getColMaps(colID) {
				colsmap = []
				for (key in g_attrMappings) {
					//message(colID+'|'+cmap[icolmap].getRelID())
					if (colID == g_attrMappings[key].relID) colsmap.push(g_attrMappings[key])
				}
				return colsmap
			}

			function getColMap(colID, attrID) {
				for (key in g_attrMappings) {
					if (g_attrMappings[key].modelName == "--debug--") {
						message(key + '\n' + colID + '\n' + attrID + '\n' + g_attrMappings[key].relID + '\n' + g_attrMappings[key].logID)
					}
					if (colID == g_attrMappings[key].relID && attrID == g_attrMappings[key].logID) return g_attrMappings[key]
				}
				return null
			}

			function getAttrMap(attrID, modName) {
				attrmaps = []
				for (key in g_attrMappings) {
					//message(colID+'|'+cmap[icolmap].getRelID())
					if ((attrID == g_attrMappings[key].logID) &&
						(modName == g_attrMappings[key].modelName)) attrmaps.push(g_attrMappings[key])
				}
				return attrmaps
			}


			function getRelationAttribute(attrCollection, attrName) {
				for (grakey in attrCollection) {
					if (attrCollection[grakey].getName() == attrName) return attrCollection[grakey]
				}
				return null
			}

			function getRelationAttrByID(attrCollection, attrID) {
				for (grakey in attrCollection) {
					if (attrCollection[grakey].getObjectID() == attrID) return attrCollection[grakey]
				}
				return null
			}


			function do1line(values) {
				modelMapping = rmodel.getRMExtendedMap().getContainerMappings().toArray();
				tabName = values[0];
				colName = values[1];
				elemName = values[2];
				attrName = values[3];
				//linemessage(elemName,attrName,tabName,colName)
				relation = null
				entity = g_entitySet.getByName(elemName);
				if (entity != null) {
					attribute = entity.getElementByName(attrName);
				} else { // assume Relation 
					relation = g_relationSet.getByName(elemName)
					if (relation != null) {
						attribute = getRelationAttribute(relation.getAttributesCollection(), attrName);
					}
				}
				table = rmodel.getTableSet().getByName(tabName);
				// Neue Tabellen werden erzeugt
				if ((table == null) && (tabName != "")) {
					rmodel.createTable(tabName);
					table = rmodel.getTableSet().getByName(tabName);
					table.setComment("Created on " + curDateStr() + " during import from " + imppath)
					g_tabanz++
				}
				if (table != null) {
					column = table.getElementByName(colName);
				} else {
					column = null
				}
				// neue Columns werden erzeugt
				if ((column == null) && (colName != "")) {
					//linemessage('neue Column',colName,tabName)
					table.createColumn(colName)
					column = table.getElementByName(colName);
					column.setComment("Created on " + curDateStr() + " during import from " + imppath)
					g_colanz++
				}
				if ((entity != null) && (table != null)) {
					mapped = getContainerMap(entity.getObjectID(), table.getObjectID())
					if (mapped == null) {
						rmodel.getRMExtendedMap().createMapping(entity, table);
						g_tabmapanz++
					}
					if ((attribute != null) && (column != null)) {
						mapped = getColMap(column.getObjectID(), attribute.getObjectID())

						if (mapped == null) {
							rmodel.getRMExtendedMap().createMapping(attribute, column);
							g_colmapanz++
						}
					}
				}
				if ((relation != null) && (table != null)) {
					mapped = getContainerMap(relation.getObjectID(), table.getObjectID())
					if (mapped == null) {
						rmodel.getRMExtendedMap().createMapping(relation, table);
						g_tabmapanz++
					}
					if ((attribute != null) && (column != null)) {
						mapped = getColMap(column.getObjectID(), attribute.getObjectID())
						if (mapped == null) {
							rmodel.getRMExtendedMap().createMapping(attribute, column);
							g_colmapanz++
						}
					}
				}
			}

			function importFile(fpath) {
				var Paths = Java.type('java.nio.file.Paths');
				var Files = Java.type('java.nio.file.Files');
				var lines = Files.readAllLines(Paths.get(fpath), Java.type('java.nio.charset.StandardCharsets').UTF_8);
				for (lnoif = 0; lnoif < lines.length; lnoif++) {
					line = lines[lnoif]
					values = line.split(";");
					for (iif = 0; iif < values.length; iif++) {
						values[iif] = trimapo(values[iif]);
					}
					if (lnoif == 0) {
						var relModel = values[0];
						// falls 1. Zeichen von Excel stammt, schneide es ab
						if (relModel.match(/^[^A-Za-z]/)) {relModel = relModel.substring(1)}
						rmodel = model.getDesign().getRelationalDesigns().getByName(relModel);
						if (rmodel == null) {
							throw new Error("\nRelational model '" + relModel + "' does not exist.\n");
						}
						getAllMappings([rmodel])
					} else
					if (lnoif == 1) {
						// skip headers
						//message(lnoif+': '+"headers= "+values);
					} else {
						//linemessage(lnoif,values.length,values);
						if (values.length>=4){
							do1line(values);
							g_lineanz++
						}
					}
				};
			}

			function importMapping() {
				//Create a file chooser
				var Filebrowse = Java.type("javax.swing.JFileChooser");
				f = new Filebrowse(g_importDirec);
				returnVal = f.showOpenDialog(null);
				if (returnVal == Filebrowse.APPROVE_OPTION) {
					imppath = f.getSelectedFile();
					//message(imppath);
				} else {
					return
				}
				g_tabanz = 0
				g_colanz = 0
				g_colmapanz = 0
				g_lineanz = 0
				g_logicalModel = model.getDesign().getLogicalDesign();
				g_entitySet = g_logicalModel.getEntitySet()
				g_relationSet = g_logicalModel.getRelationSet()
				g_inheritanceSet = g_logicalModel.getInheritanceRelationSet()
				importFile(imppath);
				message("Parsed " + g_lineanz + " lines from file " + imppath + ".\n" +
						"Created " + g_tabanz + " tables, " + g_colanz + " columns,\n" +
						"Mapped " + g_tabmapanz + " tables to entities and " + g_colmapanz + " columns to attributes") // +tabmapanz+" table- and " 

			}

			function chooseModel() {
				if (g_rmodels.length == 0) throw new Error("\n***MAPPING: no relational models available ***\n");
				if (g_rmodels.length == 1) {
					antwort = g_rmodels[0]
				} else {
					rmodel = g_rmodels[0]
					antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null,
						"Choose relational model",
						"choose model",
						QUESTIONMESSAGE,
						null,
						g_rmodels, rmodel);
				}
				return antwort
			}

			function nvl(x) {
				return x == null ? "" : x
			}


			//read the mapping of a col to attributes
			// return list [['entyname',...],['attrname',[attrObjectId,...]
			function getcolattrmap(col){
				var retval = []
				var enties = []
				var attrs = []
				var ids = []
				colmaps = getColMaps(col.getObjectID())
				if (colmaps.length > 0) {
					// Column ist gemapped
					enties = []
					attrs = []
					ids = []
					for (impcm = 0; impcm < colmaps.length; impcm++) {
						curmap = colmaps[impcm]
						parentelem = g_containerMappings[curmap.parentID]
						var attr = null
						var attrId = null
						//DEBUG if (parentelem == null){message(tab.getName()+':'+curmap.logID)} //DEBUG
						//enties.push('a');attrs.push('b');ids.push('')

						switch (parentelem.logType) {
							case ENTITYPE:
								logElem = g_entitySet.getObjectByID(parentelem.logID)
								attr = logElem.getElementByID(curmap.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl(attr.getName()))
								ids.push(nvl(attr.getObjectID()))
								break;
							case RELATYPE:
								logElem = g_relationSet.getObjectByID(parentelem.logID)
								attr = getRelationAttrByID(logElem.getAttributesCollection(), curmap.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl(attr.getName()))
								ids.push(nvl(attr.getObjectID()))
								break;
							case INHERITTYPE:
								logElem = g_inheritanceSet().getObjectByID(parentelem.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl( '???'))
								ids.push('')
								break;
							default:
								logElem = '???'
								enties.push('???')
								attrs.push(nvl(parentelem.relType))
								ids.push('')
								//throw new Error("\n  Column'"+colkey +" unknown logical mapping type: "+parent.logType);
						}
					}
				}
				retval.push(enties,attrs,ids)
				return retval
			}

			function printColsMap(tab) {
				cols = tab.getElementsCollection().toArray()
				g_writtenCols = {}
				attrentry = []
				for (icpcm = 0; icpcm < cols.length; icpcm++) {
					col = cols[icpcm]
					colkey = tab + '.' + col

					//		//FK mapped to Relations
					//		if (col.isFKColumn()) {
					//			fks = col.getAllFKs()
					//			for (ifk=0;ifk<fks.length;ifk++){
					//				fkID=fks[ifk].getObjectID()
					//				fkmaps = getContainerMaps(fkID)
					////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ifk+' :1: '+fkID+' : '+fkmaps.length)
					//				for (ir=0;ir<fkmaps.length;ir++){
					//					rela = g_relationSet.getObjectByID(fkmaps[ir].logID)
					////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ir+' :2: '+fkmaps[ir].logID+':'+rela)
					//					if (rela == null) rela = g_inheritanceSet.getObjectByID(fkmaps[ir].logID)	
					////		if (colkey=="Subentität_1.Super_Entiät_Super_Entiät_ID") message(colkey+ir+' :3: '+rela)
					//					writeMapLine(fw,tab,rela,col, null)
					//					g_writtenCols[colkey]=true
					//				}
					//			}
					//		}

					colmaps = getColMaps(col.getObjectID())
					if (colmaps.length > 0) {
						// Column ist gemapped
						for (impcm = 0; impcm < colmaps.length; impcm++) {
							curmap = colmaps[impcm]
							parentelem = g_containerMappings[curmap.parentID]
							//DEBUG if (parentelem == null){message(tab.getName()+':'+curmap.logID)} //DEBUG
							switch (parentelem.logType) {
								case ENTITYPE:
									logElem = g_entitySet.getObjectByID(parentelem.logID)
									attrName = logElem.getElementByID(curmap.logID).getName()
									break;
								case RELATYPE:
									logElem = g_relationSet.getObjectByID(parentelem.logID)
									attrName = getRelationAttrByID(logElem.getAttributesCollection(), curmap.logID).getName()
									break;
								case INHERITTYPE:
									logElem = g_inheritanceSet().getObjectByID(parentelem.logID)
									attrName = '???'
									break;
								default:
									logElem = '???'
									attrName = parentelem.relType
										//throw new Error("\n  Column'"+colkey +" unknown logical mapping type: "+parent.logType);
							}
							attrentry.push( [tab.getName(),(col == null)?'' : col.getName(),nvl(logElem.getName()),nvl(attrName)])

							g_writtenCols[colkey] = true
						}
					}
					//Jede Column wird mind. 1x geschrieben.
					if (!g_writtenCols[colkey]) {attrentry.push( [tab.getName(),col.getName(),'',''])}
				}
				return attrentry
			}
			function booltoX(b){
				return b ? 'X' : ''
			}

			function gatherDevCols(relModel) {
				var attrids
				//print all tables and columns for 1 relational model
				var tables = relModel.getTableSet().toArray();
				var attrlist = []
				for (itpc = 0; itpc < tables.length; itpc++) {
					var tab = tables[itpc]

					var cols = tab.getElementsCollection().toArray()
					for (icpcm = 0; icpcm < cols.length; icpcm++) {
						var col = cols[icpcm]
						var colkey = tab + '.' + col
						//linemessage(1,attrlist.length,tab.getName(),col.getName())

						//start with the entry for the current model table/column
						var mycolentry = [tab.getName(),col.getName()
										,col.getDatatypeText(),booltoX(col.isMandatory()),col.getDefaultValue()
										,col.getComment(),col.getNotes()
										]
						//add the Logical model mapping in the format [['enti',...],['attr',...]]
						var colattrs = getcolattrmap(col)										
						mycolentry = mycolentry.concat(colattrs[0],colattrs[1])
						//linemessage(2,attrlist.length,tab.getName(),col.getName(),mycolentry.length)

						var attrids = colattrs[2]
						// alle Modelle ausser dem aktuellen 
						var restrmodels = []
						var emptycols = []
						for (r = 0; r < g_rmodels.length; r ++){
							if (g_rmodels[r] != relModel.getName()) {
								restrmodels.push(g_rmodels[r])
								emptycols.push([],[],[])
							}
						} 
						//linemessage('gatherDevCols',restrmodels.length,attrids.length,col.getName(),tab.getName())

						if (attrids.length == 0) {
							mycolentry = mycolentry.concat(emptycols)
						} else {
							for (i = 0; i < attrids.length; i ++){
								// add to the line all mappings from all attributes to all columns in the other models
								var attrid = attrids[i]
								if (attrid != null) {
									//linemessage(colattrs[0][i],colattrs[1][i],attrids[i])
									mycolentry = mycolentry.concat(attrElements(restrmodels, attrid, false))
								}
								//linemessage(3,attrlist.length,tab.getName(),col.getName(),attrid,mycolentry.length)
							}
						}
						attrlist.push(mycolentry)
						//linemessage(5,attrlist.length,tab.getName(),col.getName(),mycolentry.length)
					}
				}
				return attrlist
			}

			function gatherCols(relModel) {
				tables = relModel.getTableSet().toArray();
				var attrlist = []
				for (itpc = 0; itpc < tables.length; itpc++) {
					tab = tables[itpc]

					containermaps = getContainerMaps(tab.getObjectID())
					if (containermaps.length == 0) {
						attrlist = attrlist.concat(printColsMap(tab))
					} else {
						//print entity/relation - Mapping of Table
						for (impc = 0; impc < containermaps.length; impc++) {
							switch (containermaps[impc].logType) {
								case ENTITYPE:
									enti = g_entitySet.getObjectByID(containermaps[impc].logID)
									if (enti != null) attrlist.push([tab.getName(), '', enti.getName(),''])
									break;
								case RELATYPE:
									rela = g_relationSet.getObjectByID(containermaps[impc].logID)
									if (rela != null) attrlist.push([tab.getName(), '',rela.getName(),''])
									break;
								case INHERITTYPE:
									//		inher=g_inheritanceSet().getObjectByID(containermaps[impc].logID)
									//		if (inher != null) writeMapLine(fw,tab,inher,null,null)
									break;
								default:
									throw new Error("\n  Table'" + tab +
										" unknown logical mapping type: " + containermaps[impc].logType);
							}
						}
						attrlist = attrlist.concat(printColsMap(tab))
					}
				}
				return attrlist
			}

			function chooseFile(direc, fileName) {
				//Create a file chooser
				//message("direc= "+direc)
				var Filebrowse = Java.type("javax.swing.JFileChooser");
				var File = Java.type("java.io.File");
				f = new Filebrowse(direc);
				f.setSelectedFile(new File(fileName));
				returnVal = f.showSaveDialog(null);
				if (returnVal == Filebrowse.APPROVE_OPTION) {
					return f.getSelectedFile();
				} else {
					return null
				}
			}

			function createFile(fileName) {
				//Create a file chooser
				var FileWriter = Java.type('java.io.FileWriter')
				fw = new FileWriter(fileName);
				return fw
			}


			function getColName(rmod, tabID, colID) {
				tab = rmod.getTableSet().getObjectByID(tabID)
				col = tab.getElementByID(colID)
				return tab + '.' + col
			}

			function colProperty(pcurmodel, tabname, colname, propName) {
				table = pcurmodel.getTableSet().getByName(tabName);
				if (table == null) return ""
				column = table.getElementByName(colName);
				extID = column.getProperty(propName)
				return ((extID == null) || (extID == ".")) ? "" : extID
			}

			function findFK(fks, fkID) {
				for (iloc in fks) {
					//		if (fkID == "8AEA1CA4-3B90-4F1D-37AE-8A0FD50F8996") {message(fks[iloc].getTable()+fks[iloc].getObjectID()+fks[iloc])}
					if (fks[iloc].getObjectID() == fkID) return fks[iloc]
				}
				return null
			}

			function tabList(maps, elemType, pcurmodel) {
				tlretval = []
				if (maps != null) {
					if (elemType != 'Entity') {
						fks = pcurmodel.getFKIndexAssociationSet().toArray()
					}
					for (i in maps) {
						if (elemType == 'Entity') {
							tabName = maps[i].tableName
						} else {
							fk = findFK(fks, maps[i].relID)
							if (fk != null) {
								tabName = fk.getTable()
							} else {
								tabName = maps[i].tableName // falls es m:n ist ist es eine Table
							}
						}
						tlretval.push(tabName.getName())
					}
				}
				//message('tablist= '+tlretval+ '|'+elemType)
				return tlretval
			}

			function elements(rmodels, logID, elemType, nurX) {
				elretval = []
				for (ih = 0; ih < rmodels.length; ih++) {
					var curmodel = rmodels[ih]
					maps = getLogMap(logID, curmodel)
					if (maps.length > 0) {
						if (nurX) {
							elretval.push(['X'])
						} else {
							elretval.push(tabList(maps, elemType, curmodel), [], [])
						}
					} else {
						if (nurX) {
							elretval.push([])
						} else {
							elretval.push([], [], [])
						}
					}
					// Extra columns are empty
				}
				return elretval
			}

			var g_curmodel = null // for the sortattrmaps function			
			function sortattrmaps(a,b){
				var atab = g_containerMappings[a.parentID].tableName
				var acol = g_curmodel.getTableSet().getByName(atab).getElementByID(a.relID)
				var btab = g_containerMappings[b.parentID].tableName
				var bcol = g_curmodel.getTableSet().getByName(btab).getElementByID(b.relID)
				if (atab < btab) {return -1 }
				if (atab > btab) {return 1}
				return (acol < bcol) ? -1 : (acol > bcol) ? 1 : 0
			}

			function attrElements(rmodels, attrID, nurX) {
				var aeretval = []
				var attrlist = []
				var tabNames = []
				var colNames = []
				var colIDs = []
				for (irmpm = 0; irmpm < rmodels.length; irmpm++) {
					g_curmodel = rmodels[irmpm]
					//linemessage('attrElements 1',rmodels.length,attrID,g_curmodel.getName())
					var attrmaps = getAttrMap(attrID, g_curmodel.getName())
						//		if (attrID == '55CABD5F-9462-BF35-239C-E8A1A1D0848C') {
						//			message(g_curmodel.getName()+':'+attrID+':'+attrmaps.length)
						//		}
					//linemessage('attrElements 2',attrmaps.length,g_curmodel.getName())
					if (attrmaps.length > 0) {
						if (nurX) {
							attrlist = [
								['X']
							]
						} else {
							attrlist = [],
							tabNames = []
							colNames = []
							colIDs = []
							//SORT
							var attrmaplist = []
							for (var key in attrmaps) {
							    attrmaplist.push( attrmaps[key] );
							}
							attrmaplist.sort(sortattrmaps);
							for (var amidx=0;amidx<attrmaplist.length;amidx++) {
								var attrmap = attrmaplist[amidx]
								//linemessage('attrElements 3',attrmap.parentID,attrmap.relID,g_curmodel.getName())
							//SORT
							//for (key in attrmaps) {
							//attrmap = attrmaps[key]
								tabName = g_containerMappings[attrmap.parentID].tableName
								colName = g_curmodel.getTableSet().getByName(tabName).getElementByID(attrmap.relID)
								tabNames.push(tabName.getName())
								colNames.push(colName.getName())
								colIDs.push(colProperty(g_curmodel, tabName, colName, EXTIDPROPNAME))
							}
							//				if (attrID == '55CABD5F-9462-BF35-239C-E8A1A1D0848C') {
							//					message('tabName1='+tabNames+'\ncolNames='+colNames+'\ncolIDs='+colIDs)
							//				}

							//tabNames = tabNames.slice(0, -1)
							//colNames = colNames.slice(0, -1)
							//colIDs = colIDs.slice(0, -1)
							attrlist = [tabNames, colNames, colIDs]
						}
					} else {
						attrlist = nurX ? [
							[]
						] : [
							[],
							[],
							[]
						]
					}
					aeretval = aeretval.concat(attrlist)
				}
				return aeretval
			}


			function logicalElement(rmodels, logElem, nurX) {
				var leretval = []
				var elemID = logElem.getObjectID()
				var attrs = null
				var entyentry 
				if (logElem.getObjectTypeName() == 'Entity') {
					entyentry = [logElem.getName(), '']
					entyentry = entyentry.concat(elements(rmodels, logElem.getObjectID(), logElem.getObjectTypeName(), nurX))
					leretval.push(entyentry)
					attrs = logElem.getElementsCollection().toArray()
				} else if (logElem.getObjectTypeName() == 'Relation') {
					if (logElem.isManyToMany()) { // FK-Mapping ist nicht trivial bei seltsamen Modellen
						entyentry = [logElem.getName(), '']
						entyentry = entyentry.concat(elements(rmodels, logElem.getObjectID(), logElem.getObjectTypeName(), nurX))
						leretval.push(entyentry)
						attrs = logElem.getAttributesCollection().toArray()
					}
				} else { // assume inheritance
					// Inheritance sind schon entities line += elements(rmodels,logElem.getObjectID(),logElem.getObjectTypeName(),nurX)
					// Inheritance becomes fk-columns
				}
				//message('logical Elements before attrs= '+logElem.getName()+'|'+leretval)
				if (attrs != null) {
					for (iattrac = 0; iattrac < attrs.length; iattrac++) {
						var attr = attrs[iattrac]
						var attrID = attr.getObjectID()
						var key = elemID + '.' + attrID
						attrentry = [logElem.getName(), attr.getName()] //DEBUG  ,attrID]
						attrentry = attrentry.concat(attrElements(rmodels, attrID, nurX))
						leretval.push(attrentry)
							//throw new Error("\nattrs: " + leretval + "\n");
					}
				}
				//message('logical Elements= '+logElem.getName()+'|'+leretval)
				return leretval
			}

			//	function printElementGroup(rmodels, group, nurX) {
			function mappings2json(rmodels, group, nurX) {
				m2jretval = []
				if (group != null) {
					for (ig = 0; ig < group.length; ig++) {
						m2jretval = m2jretval.concat(logicalElement(rmodels, group[ig], nurX))
					}
				}
				//message('mappings2json= '+retval)
				return m2jretval
			}

			function escapeexcelchars(s){
				var retval = s.replace(/"/g, "'") //  " sollte EXCELESCCHAR sein ist aber umständlich
				if (retval.match(/\n/)) {retval = EXCELESCCHAR + retval + EXCELESCCHAR}
				return retval
			}
			function printline(fw, line) {
//				for (zi = 0; zi < line.length; zi++) {
//					field = line[zi]
				forEach(line,
					function print1ine(field,idx){
						if (idx > 0) {
							fw.write(EXCELCSVSEP)
						}
						try {
							if (typeof field == 'string') {
								fw.write(escapeexcelchars(field) )
							} else if (field.length == 0) {
								fw.write('') // empty List
							} else if (field.length == 1) {
								fw.write(escapeexcelchars(field[0])) // single string in List
							} else {
								// list of Strings
								fw.write(escapeexcelchars(field.join(EXCELMULTILINESEP)) )
							}
						} catch (err) {linemessage(typeof field, field,line); throw err}
					}
				)				
				fw.write(EXCELLINEEND)
			}

			function printlines(fw, entry) {
				for (ie = 0; ie < entry.length; ie++) {
					line = entry[ie]
						// es ist eine Liste von Zeilen
					printline(fw, line)
				}
			}

			function json2csv(fw, allMapping) {
				fw.write(EXCELBOM)
				for (key in allMapping) {
					entry = allMapping[key]
					switch (key) {
						case "model":
						case "header":
						case "subheader":
							fw.write(entry.join(EXCELCSVSEP))
							fw.write(EXCELLINEEND)
							break;
						case "attrlist":
							printlines(fw, entry)
							break;
						case "footer":
							fw.write(entry)
							fw.write(EXCELLINEEND)
							break;
						default:
							fw.write('unbekannter Eintrag ' + key)
					}
				}
			}

			function gatherModel() {
				g_logicalModel = model.getDesign().getLogicalDesign();
				g_entitySet = g_logicalModel.getEntitySet()
				g_relationSet = g_logicalModel.getRelationSet()
				g_inheritanceSet = g_logicalModel.getInheritanceRelationSet()
				g_rmodels = model.getDesign().getRelationalDesigns().toArray();
			}

			function printjson(fw, format, allmapping) {
				switch (format) {
					case FORMATJSON:
						fw.write(JSON.stringify(allmapping, null, 2)); // spacing level = 2)
						break;
					case FORMATCSV:
						json2csv(fw, allmapping)
						break;
					default:
						throw new Error("invalid format " + format)
				}
			}

			function printMatrix(fw, nurX, format) {
				gatherModel()

				getAllMappings(g_rmodels)

				if (nurX) {
					allmapping = {
						"header": ['entity', 'attr']
					}
					for (ih = 0; ih < g_rmodels.length; ih++) {
						//throw new Error("\nrmodel: " + g_rmodels[ih].getName() + '|'+g_rmodels[ih] + "\n");
						allmapping["header"].push(g_rmodels[ih].getName())
					}
				} else {
					allmapping = {
						"header": ['Information Model', ''],
						"subheader": ['entity', 'attr']
					}
					for (ih = 0; ih < g_rmodels.length; ih++) {
						allmapping["header"].push(g_rmodels[ih].getName(), '', '')
						allmapping["subheader"].push('table', 'column', 'ID')
					}
				}

				//throw new Error("\nheaders: " + allmapping["header"] + "\n");
				allmapping["attrlist"] = mappings2json(g_rmodels, g_entitySet.toArray(), nurX)
				allmapping["attrlist"] = allmapping["attrlist"].concat(mappings2json(g_rmodels, g_relationSet.toArray(), nurX))

				allmapping["footer"] = 'created by ODM, ' + curDateStr();
				printjson(fw, format, allmapping)
			}

			function printCVS(fw, format,relModel) {

				// lies alle Mappings des gewählten Modells
				getAllMappings([relModel])
				allmapping = {
					"model": [relModel.getName(), '', 'Information Model', ''],
					"header": ['tableName', 'columnName','entityName', 'attrName'],
					"attrlist": gatherCols(relModel)
				}
				printjson(fw, format, allmapping)
			}

			function printDevCVS(fw, format,relModel) {
				// lies alle Mappings des gewählten Modells
				mymodelname = relModel.getName()
				allmapping = {
					"model": [mymodelname,'','','','','','', 'Information Model',''],
					"header": ['tableName', 'columnName','datatype','mand.','def. value','descr','rules','entity','attribute'],
					"attrlist": gatherDevCols(relModel)
				}
				// Add all relational models except myself to the header
				for (ih = 0; ih < g_rmodels.length; ih++) {
					if (g_rmodels[ih].getName() != mymodelname) {
						//linemessage(ih,g_rmodels[ih].getName(), mymodelname)
						allmapping["model"].push(g_rmodels[ih].getName(), '', '')
						allmapping["header"].push('table','column','ID')
					}
				}

				printjson(fw, format, allmapping)
			}

			function chooseoutputfilename(pfilename, pformat) {
				fileName = chooseFile(g_exportDirec, pfilename +
					((pformat == FORMATJSON) ?'.js' : ((pformat == FORMATCSV) ?'.csv' :'txt')))
				return fileName
			}

			function outputformat() {
				var formatauswahl = [FORMATJSON, FORMATCSV]
				antwort = Java.type("javax.swing.JOptionPane").showInputDialog(null,
					"Output format",
					"choose output format",
					QUESTIONMESSAGE,
					null,
					formatauswahl, FORMATCSV);
				return antwort
			}

			function print1Mapping() {
				gatherModel()
				var relModel = chooseModel();
				if (relModel == null) return;

				format = outputformat()
				if (format == null) {
					return 
				}
				filename = chooseoutputfilename(relModel.getName(), format)
				if (filename == null) {
					return 
				} else {
					fw = createFile(filename)
				}
				printCVS(fw, format,relModel)
				fw.close();
				message("Mapping file " + fileName + " for model " + relModel.getName() + " created.");
			}

			function printDevMapping() {
				gatherModel()
				var relModel = chooseModel();
				if (relModel == null) return;

				format = outputformat()
				if (format == null) {
					return null
				}
				filename = chooseoutputfilename(relModel.getName()+'_dev', format)
				if (filename == null) {
					return
				} else {
					fw = createFile(filename)
				}
				getAllMappings(g_rmodels)
				printDevCVS(fw, format,relModel)
				fw.close();
				message("Mapping file " + fileName + " for model " + relModel.getName() + " created.");
			}


			function printAllMapping(nurX) {
				format = outputformat()
				if (format == null) {
					return null
				}
				filename = model.getDesign().getName()
				filename = chooseoutputfilename(filename + (nurX ? 'X' : ''), format)
				if (filename == null) {
					return
				} else {
					fw = createFile(filename)
				}
				printMatrix(fw, nurX, format)
				fw.close();
				message("Mapping file " + fileName + " created.");
			}

