			function nvl(x) {
				return x == null ? "" : x
			}


			//read the mapping of a col to attributes
			// return list [['entyname',...],['attrname',[attrObjectId,...]
			function getcolattrmap(col){
				var retval = []
				var enties = []
				var attrs = []
				var ids = []
				colmaps = getColMaps(col.getObjectID())
				if (colmaps.length > 0) {
					// Column ist gemapped
					enties = []
					attrs = []
					ids = []
					for (impcm = 0; impcm < colmaps.length; impcm++) {
						curmap = colmaps[impcm]
						parentelem = g_containerMappings[curmap.parentID]
						var attr = null
						var attrId = null
						//DEBUG if (parentelem == null){message(tab.getName()+':'+curmap.logID)} //DEBUG
						//enties.push('a');attrs.push('b');ids.push('')

						switch (parentelem.logType) {
							case ENTITYPE:
								logElem = g_entitySet.getObjectByID(parentelem.logID)
								attr = logElem.getElementByID(curmap.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl(attr.getName()))
								ids.push(nvl(attr.getObjectID()))
								break;
							case RELATYPE:
								logElem = g_relationSet.getObjectByID(parentelem.logID)
								attr = getRelationAttrByID(logElem.getAttributesCollection(), curmap.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl(attr.getName()))
								ids.push(nvl(attr.getObjectID()))
								break;
							case INHERITTYPE:
								logElem = g_inheritanceSet().getObjectByID(parentelem.logID)
								enties.push(nvl(logElem.getName()))
								attrs.push(nvl( '???'))
								ids.push('')
								break;
							default:
								logElem = '???'
								enties.push('???')
								attrs.push(nvl(parentelem.relType))
								ids.push('')
								//throw new Error("\n  Column'"+colkey +" unknown logical mapping type: "+parent.logType);
						}
					}
				}
				retval.push(enties,attrs,ids)
				return retval
			}

