// Functions (showhideelements) for abstraction-level display in subviews.

//InitVars
var CODEVERSION = '0.2'
var PLAINMESSAGE = 1
var ERRORMESSAGE = 0
var WARNINGMESSAGE = 2
var QUESTIONMESSAGE = 3

//Spec
var minZoomLevel = 0
var maxZoomLevel = 5

//HelperFunctions start
function fullmessage(msg,type) {
    Java.type("javax.swing.JOptionPane").showMessageDialog(null, msg,'ODM-Message', type)
}

function promptmessage(msg,type) {
    retval = Java.type("javax.swing.JOptionPane").showInputDialog(null, msg,'ODM-Promtbox', type)
    return retval
}

function confirmmessage(msg,type) {
    retval = Java.type("javax.swing.JOptionPane").showConfirmDialog(null, msg,'ODM-Confirmbox', type)
    if (retval == 0) {
        return true
    }else{
        return false
    }
}

function error(msg) {
    fullmessage(msg,ERRORMESSAGE)
}

function message(msg) {
    fullmessage(msg,PLAINMESSAGE)
}

function prompt(msg){
    retval = promptmessage(msg,QUESTIONMESSAGE)
    return retval
}

function confirm(msg){
    retval = confirmmessage(msg,0)
    return retval
}

function isNumeric(n) {
    return !isNaN(parseFloat(n)) && isFinite(n)
}

function getMinMax(checkObj){
    minzl = checkObj.getProperty("minzoomlevel")  
    maxzl = checkObj.getProperty("maxzoomlevel")
    if (!(isNumeric(minzl))){
        minzl = minZoomLevel
    }
    if (!(isNumeric(maxzl))){
        maxzl = maxZoomLevel
    }    
}

function getsubview(thissv){
    var svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    var retval = null
    for (var vv=0;vv<svlist.length;vv++){
        var checksv = svlist[vv]
        if (((thissv == null) && (checksv.isCurrentDPV())) || (thissv == checksv)) {
            var retval = checksv
        }
    }
    return retval
}

function getcommentvalue(srcobj,srcvalue){      
    var retval = null
    var commentlines = []
    var commentlines = srcobj.getComment().split("\n")
    for (var vv=0;vv<commentlines.length;vv++){
        if (commentlines[vv].contains(srcvalue+"=")){
            var retval = commentlines[vv].replace(srcvalue+"=","")
        }
    }
    if (retval == null) {
        error("No "+srcvalue+" definition in view "+srcobj+" found!")
    }
    return retval
}

function getzoomlevelprompt(){
    retval = prompt('Choose desired zoomlevel');
    if (!(isNumeric(retval))) {
        message("No zoomlevel detected\nDefault zoomlevel: "+minZoomLevel);
        retval = minZoomLevel;
    }
    return retval;
}
//HelperFunctions end

function dev_createsubview(){
    //InitPart begin
    logger = model.getAppView()
    sv = getsubview(null)
    if (sv == null){
        return
    }
    newzlevel = getzoomlevelprompt()
    sventities = sv.getTVShapes()
    var list = []

    logger.logMessage("\n")

    for (var ie=0;ie<sventities.length;ie++){
        sventity = sventities[ie]
        entity = model.getEntitySet().getByName(sventity)
        if (entity != null) {
            getMinMax(entity)
            if (!((newzlevel > maxzl) || (newzlevel < minzl))){
                tv0 = entity.getFirstViewForDPV(sv)
                cell0 = tv0.getCellView().getCell()
                list.push(cell0)    
            }
        }
    }
    sv.getWorkSpace().setSelectionCells(list)
    sv.createSubViewFromSelected()

    svlist = model.getDesign().getLogicalDesign().getListOfSubviews()
    for (var vv=0;vv<svlist.length;vv++){
        thissv = svlist[vv];
        if (thissv.isCurrentDPV()) {
            thissv.setComment("zoomlevel="+newzlevel+"\nparentview="+sv)
        }
    }

}

function dev_initzoomlevel(){
    //InitPart begin
    logger = model.getAppView()
    logger.logMessage("\n")

    overwrite = confirm("Overwrite existing definitions?")

    entities = model.getEntitySet().toArray()
    relations = model.getRelationSet().toArray()

    for (var ie=0;ie<entities.length;ie++){
        entity = entities[ie]
        if (overwrite){
            entity.setProperty("minzoomlevel",minZoomLevel)
            entity.setProperty("maxzoomlevel",maxZoomLevel)
        }else{
            minzl = entity.getProperty("minzoomlevel")  
            maxzl = entity.getProperty("maxzoomlevel")
            if (!(isNumeric(minzl))){
                entity.setProperty("minzoomlevel",minZoomLevel)
            }
            if (!(isNumeric(maxzl))){
                entity.setProperty("maxzoomlevel",maxZoomLevel)
            }
        }
        attrs = entity.getAttributes().toArray()
        for (var ia=0;ia<attrs.length;ia++) {
            attr = attrs[ia]
            if (overwrite){
                attr.setProperty("minzoomlevel",minZoomLevel)
                attr.setProperty("maxzoomlevel",maxZoomLevel)
            }else{
                minzl = attr.getProperty("minzoomlevel")  
                maxzl = attr.getProperty("maxzoomlevel")
                if (!(isNumeric(minzl))){
                    attr.setProperty("minzoomlevel",minZoomLevel)
                }
                if (!(isNumeric(maxzl))){
                    attr.setProperty("maxzoomlevel",maxZoomLevel)
                }
            }

        }
    }
    for (var ir=0;ir<relations.length;ir++){
        relation = relations[ir]
        if (overwrite){
            relation.setProperty("minzoomlevel",minZoomLevel)
            relation.setProperty("maxzoomlevel",maxZoomLevel)
        }else{
            minzl = relation.getProperty("minzoomlevel")  
            maxzl = relation.getProperty("maxzoomlevel")
            if (!(isNumeric(minzl))){
                relation.setProperty("minzoomlevel",minZoomLevel)
            }
            if (!(isNumeric(maxzl))){
                relation.setProperty("maxzoomlevel",maxZoomLevel)
            }
        }
    }
}

function showhideelements(){
    //InitPart begin
    logger = model.getAppView()
    sv = getsubview(null)  
    svzlevel = getcommentvalue(sv,"zoomlevel")
    svpview = getcommentvalue(sv,"parentview")  
    if ((svzlevel == null) || (svpview == null)){
        return
    }
    pv = getsubview(svpview)
    pvzlevel = getcommentvalue(pv,"zoomlevel")
    if (pvzlevel == null) {
        return
    }

    entities = model.getEntitySet().toArray()
    sventities = sv.getTVShapes()
    svrelations = sv.getTVConnectors()

    relations = model.getRelationSet().toArray()
    pventities = pv.getTVShapes()
    pvrelations = pv.getTVConnectors()    

    logger.logMessage("\n")
    //InitPart end

    //ZoomlevelCheck Entity begin
    logPrefix = "ZoomlevelCheck > Entity"
    logger.logMessage(logPrefix)
    showElements = []
    hideElements = []
    showAttributes = []
    hideAttributes = []    
    for (var ie = 0; ie < entities.length; ie++){
        entity = entities[ie]
        isOnSV = false
        for (var ie2=0;ie2<sventities.length;ie2++){
            sventity = sventities[ie2]
            if (entity.getName() == sventity){
                isOnSV = true               
                attrs = entity.getAttributes().toArray()
                for (var ia=0;ia<attrs.length;ia++) {
                    attr = attrs[ia]
                    getMinMax(attr)
                    isOnSVEntity = true
                    hiddenElements = sventity.getHiddenElements()
                    for (var ia2=0;ia2<hiddenElements.length;ia2++) {
                        hiddenElement = hiddenElements[ia2]
                        if (attr == hiddenElement){
                            isOnSVEntity = false
                        }
                    }
                    if ((svzlevel > maxzl) || (svzlevel < minzl)) {
                        if (isOnSVEntity) {
                            hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+attr)    
                        }
                    }else{
                        if (!(isOnSVEntity)){
                            showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)    
                        }
                    }
                }                             
            }
        }
        getMinMax(entity)
        if ((svzlevel > maxzl) || (svzlevel < minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+entity)    
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+entity)    
            }
        }
    }
    for (var i=0;i<showElements.length;i++){
        logger.logMessage(showElements[i])
    }
    for (var i=0;i<hideElements.length;i++){
        logger.logMessage(hideElements[i])
    }
    for (var i=0;i<showAttributes.length;i++){
        logger.logMessage(showAttributes[i])
    }
    for (var i=0;i<hideAttributes.length;i++){
        logger.logMessage(hideAttributes[i])
    }
    //ZoomlevelCheck Entity end

    //ZoomlevelCheck Relation begin
    logPrefix = "ZoomlevelCheck > Relation"
    logger.logMessage(logPrefix)
    showElements = []
    hideElements = []
    for (var ir = 0; ir < relations.length; ir++){
        relation = relations[ir]
        isOnSV = false
        for (var ir2=0;ir2<svrelations.length;ir2++){
            svrelation = svrelations[ir2]
            if (relation.getName() == svrelation){
                isOnSV = true
            }
        }
        getMinMax(relation)
        if ((svzlevel > maxzl) || (svzlevel < minzl)){
            if (isOnSV) {
                hideElements.push(logPrefix+" > HIDE: "+relation)    
            }
        }else{
            if (!(isOnSV)){
                showElements.push(logPrefix+" > SHOW: "+relation)    
            }
        }
    }   
    for (var is=0;is<showElements.length;is++){
        logger.logMessage(showElements[is])
    }
    for (var ih=0;ih<hideElements.length;ih++){
        logger.logMessage(hideElements[ih])
    }
    //ZoomlevelCheck Relation end

    //ParentViewCompare Entity begin
    logPrefix = "ParentViewCompare > Entity"
    logger.logMessage(logPrefix)
    showAttributes = []
    hideAttributes = []
    for (var ie = 0; ie < pventities.length; ie++){
        pventity = pventities[ie]
        entity = model.getEntitySet().getByName(pventity)
        var thissventity = null
        isOnSV = false
        for (var ie2=0;ie2<sventities.length;ie2++){
            sventity = sventities[ie2]
            if (pventity.toString() == sventity.toString()){
                isOnSV = true
                var thissventity = sventity
            }
        }
        if (!(isOnSV)){            
            if (entity != null){
                getMinMax(entity)
                if ((pvzlevel > maxzl) || (pvzlevel < minzl)){
                    logger.logMessage(logPrefix+" > SHOW: "+entity)
                }
            }
        }else{
            pvhiddenElements = pventity.getHiddenElements()
            svhiddenElements = thissventity.getHiddenElements()
            for (var ih=0;ih<pvhiddenElements.length;ih++){
                pvhiddenElement = pvhiddenElements[ih]
                getMinMax(pvhiddenElement)
                if (!((pvzlevel > maxzl) || (pvzlevel < minzl))) {
                    for (var ih2=0;ih2<svhiddenElements.length;ih2++){
                        if (pvhiddenElements[ih] == svhiddenElements[ih2]){
                            isOnSV = false
                        }
                    }
                    if (isOnSV){
                        hideAttributes.push(logPrefix+" ("+entity+") > Attribute > HIDE: "+pvhiddenElements[ih])
                    } 
                }
            }
            if (entity != null){
                attrs = entity.getAttributes().toArray()
                for (var ia=0;ia<attrs.length;ia++) {
                    attr = attrs[ia]
                    getMinMax(attr)
                    isOnPV = true
                    if ((pvzlevel > maxzl) || (pvzlevel < minzl)) {
                        for (var ih=0;ih<pvhiddenElements.length;ih++){
                            if (pvhiddenElements[ih] == attr){
                                isOnPV = false
                            }
                        }
                        if (isOnPV){
                            isOnSV = true
                            for (var ih=0;ih<svhiddenElements.length;ih++){
                                if (svhiddenElements[ih] == attr){
                                    isOnSV = false
                                }
                            }
                            if (!(isOnSV)){
                                showAttributes.push(logPrefix+" ("+entity+") > Attribute > SHOW: "+attr)
                            }
                        }
                    }
                }        
            }
        }
    }
    for (var ie = 0; ie < sventities.length; ie++){
        sventity = sventities[ie]
        isOnPV = false
        for (var ie2=0;ie2<pventities.length;ie2++){
            pventity = pventities[ie2]
            if (pventity.toString() == sventity.toString()){
                isOnPV = true
            }
        }
        if (!(isOnPV)){
            logger.logMessage(logPrefix+" > HIDE: "+sventity) 
        }
    }
    for (var i=0;i<showAttributes.length;i++){
        logger.logMessage(showAttributes[i])
    }
    for (var i=0;i<hideAttributes.length;i++){
        logger.logMessage(hideAttributes[i])
    }
    //ParentViewCompare Entity end

    //ParentViewCompare Relation begin
    logPrefix = "ParentViewCompare > Relation"
    logger.logMessage(logPrefix)
    for (var ir = 0; ir < pvrelations.length; ir++){
        pvrelation = pvrelations[ir]
        isOnSV = false
        for (var ir2=0;ir2<svrelations.length;ir2++){
            svrelation = svrelations[ir2]
            if (pvrelation.toString() == svrelation.toString()){
                isOnSV = true
            }
        }
        if (!(isOnSV)){
            logger.logMessage(logPrefix+" > SHOW: "+pvrelation)    
        }
    }
    for (var ir = 0; ir < svrelations.length; ir++){
        svrelation = svrelations[ir]
        isOnPV = false
        for (var ir2=0;ir2<pvrelations.length;ir2++){
            pvrelation = pvrelations[ir2]
            if (pvrelation.toString() == svrelation.toString()){
                isOnPV = true
            }
        }
        if (!(isOnPV)){
            logger.logMessage(logPrefix+" > HIDE: "+svrelation)    
        }
    }
    //ParentViewCompare Relation end   
}
